      if (mag < 0.16) {
        this._applySmartViewerTransform();
        return;
      }
      const maxSpeed = 5.4;
      if (mag > maxSpeed) {
        vx = (vx / mag) * maxSpeed;
        vy = (vy / mag) * maxSpeed;
      }
